from typing import Any, List, Dict, Optional

def run(left: List[Dict[str, Any]], right: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Validate left records
    left_fields = {"lead_id", "sender_email", "lead_name", "company", "subject"}
    for record in left:
        for field in left_fields:
            if field not in record:
                raise ValueError(field)

    # Validate right records
    right_fields = {"contact_id", "email", "name", "company", "status"}
    for record in right:
        for field in right_fields:
            if field not in record:
                raise ValueError(field)

    # Build normalized right map
    def normalize_email(s: str) -> str:
        return s.lower().strip()

    right_norm_map: Dict[str, List[Dict[str, Any]]] = {}
    for r in right:
        k = normalize_email(r['email'])
        if k not in right_norm_map:
            right_norm_map[k] = []
        right_norm_map[k].append(r)

    # Process left records
    results = []
    for l in left:
        k = normalize_email(l['sender_email'])

        if not k or k not in right_norm_map:
            results.append({
                "left_id": l['lead_id'],
                "right_id": None,
                "status": "contact_not_found"
            })
            continue

        matches = right_norm_map[k]
        if len(matches) > 1:
            results.append({
                "left_id": l['lead_id'],
                "right_id": None,
                "status": "manual_review"
            })
            continue

        # Single match
        r = matches[0]
        right_id = r['contact_id']

        # Check company match (equals_ci)
        left_company = l['company']
        right_company = r['company']

        if not isinstance(left_company, str) or not isinstance(right_company, str):
            results.append({
                "left_id": l['lead_id'],
                "right_id": right_id,
                "status": "company_mismatch"
            })
            continue

        if left_company.strip().lower() != right_company.strip().lower():
            results.append({
                "left_id": l['lead_id'],
                "right_id": right_id,
                "status": "company_mismatch"
            })
            continue

        # Check name match (equals_ci)
        left_name = l['lead_name']
        right_name = r['name']

        if not isinstance(left_name, str) or not isinstance(right_name, str):
            results.append({
                "left_id": l['lead_id'],
                "right_id": right_id,
                "status": "name_mismatch"
            })
            continue

        if left_name.strip().lower() != right_name.strip().lower():
            results.append({
                "left_id": l['lead_id'],
                "right_id": right_id,
                "status": "name_mismatch"
            })
            continue

        # All checks pass
        results.append({
            "left_id": l['lead_id'],
            "right_id": right_id,
            "status": "auto_create_and_log"
        })

    return results
